 const name=textValue(r.name,'員工姓名',150);if(names.has(name))fail(`員工名單中「${name}」重複，請保留一列。`);names.add(name);const status=r.status||'未註記';if(!['未註記','在職','離職','未到職'].includes(status))fail(`${name}的在離職狀態不正確。`);
