async function effectiveSnapshot(bucket,snapshot){return reviewedSnapshot(bucket,snapshot)}

function employeeLoginState(user,person){
 if(!person)return '不在員工名單';
 const status=employmentStatus(person);if(status!=='在職')return status;
 if(user.directoryEmployment){const status=employmentStatus(user.directoryEmployment);if(status!=='在職')return status}
 if(!user||user.enabled===false||!user.hash||!user.salt)return '未設定密碼';
 return '已啟用';
}
async function prepareEmployeeAccounts(input,roster,existing,preview=false){
 if(!Array.isArray(input.accounts)||!input.accounts.length||input.accounts.length>5000)fail('請提供 1～5,000 筆員工帳號。',422);
 const ids=new Set(),names=new Set(),rows=[];
 for(const a of input.accounts){
  const name=String(a.name??'').trim(),id=String(a.id??'').trim(),password=a.password??'';
  if(!name||!roster.some(e=>e.name===name))fail(`「${name}」不在網站保留名冊，請先更新員工資料。`,422);
  if(names.has(name)||(id&&ids.has(id)))fail('檔案中工號或姓名重複，請先核對。',422);names.add(name);if(id)ids.add(id);
  if(id&&!/^[A-Za-z0-9._-]{1,30}$/.test(id))fail('工號請填 1～30 位英數字、點、底線或減號。',422);
  if(typeof password!=='string')fail(`「${name}」密碼格式不正確。`,422);
  const hasPassword=password.trim().length>0;
  if(hasPassword&&(!id||password.length<4||password.length>128))fail(`「${name}」需有工號，初始密碼請填 4～128 個字元。`,422);
  if(id&&existing.some(u=>(u.id===id&&u.name!==name)||(u.name===name&&u.id!==id)))fail(`「${name}」工號與既有帳號對應不一致，請先核對。`,409);
  let directoryEmployment;
  if(a.hireDate!==undefined||a.leaveDate!==undefined){const person=roster.find(e=>e.name===name);directoryEmployment={status:person.status||'未註記',hireDate:employmentDate(a.hireDate,`${name}到職日`),leaveDate:employmentDate(a.leaveDate,`${name}離職日`),...(person.knownActiveBy?{knownActiveBy:person.knownActiveBy}:{})};if(directoryEmployment.hireDate&&directoryEmployment.leaveDate&&directoryEmployment.leaveDate<directoryEmployment.hireDate)fail(`${name}離職日不得早於到職日。`,422)}
  rows.push({id,name,password,hasPassword,directoryEmployment});
 }
 const users=structuredClone(existing),counts={created:0,reset:0,kept:0,disabled:0,withoutId:0};
 for(const a of rows){
  let old=users.find(u=>u.name===a.name),person=roster.find(e=>e.name===a.name);
  if(!a.id){counts.withoutId++;if(old){Object.assign(old,{enabled:false,hash:null,salt:null,revision:crypto.randomUUID(),updatedAt:new Date().toISOString(),...(a.directoryEmployment?{directoryEmployment:a.directoryEmployment}:{})});counts.disabled++}continue}
  const enabled=a.hasPassword&&employmentStatus(a.directoryEmployment||person)==='在職'&&employmentStatus(person)==='在職';
  if(!enabled){
   const next={id:a.id,name:a.name,enabled:false,salt:null,hash:null,revision:crypto.randomUUID(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),...(a.directoryEmployment?{directoryEmployment:a.directoryEmployment}:{})};
   if(old)Object.assign(old,next);else users.push(next);counts.disabled++;continue;
  }
  if(old&&old.enabled!==false&&old.hash&&input.resetPasswords!==true){if(a.directoryEmployment)old.directoryEmployment=a.directoryEmployment;old.enabled=true;counts.kept++;continue}
  const salt=preview?'':authHex(crypto.getRandomValues(new Uint8Array(16))),hash=preview?'':await authPassword(a.password,salt),next={id:a.id,name:a.name,enabled:true,salt,hash,revision:crypto.randomUUID(),createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),...(a.directoryEmployment?{directoryEmployment:a.directoryEmployment}:{})};
  if(old){Object.assign(old,next);counts.reset++}else{users.push(next);counts.created++}
 }
 const enabled=users.filter(u=>employeeLoginState(u,roster.find(e=>e.name===u.name))==='已啟用'||(preview&&u.enabled===true)).length;
 return {users,summary:{...counts,total:users.length,enabled,blocked:users.length-enabled}};
}
async function employeeDirectorySync(request,bucket){
 writeGuard(request);const input=await employeeBody(request,1024*1024),current=await readCurrent(bucket),auth=await employeeUsers(bucket);
 if(input.preview!==true&&input.expectedRevision!==current.record.revision)fail('名單已變更，請重新預覽再更新。',409);
 if(!Array.isArray(input.employees)||!input.employees.length)fail('請提供完整員工名單。',422);
 const raw=normalizedRaw({records:[],employees:input.employees,rosterOnly:true}),merged=mergeEmployees(current.record.snapshot.roster||[],raw.employees);
 if(input.accounts?.length!==raw.employees.length||input.accounts.some(a=>!raw.employees.some(e=>e.name===a.name)))fail('帳號與員工名單必須逐人對應。',422);
 const prepared=await prepareEmployeeAccounts(input,merged.roster,auth.users,input.preview===true);
 const summary={...prepared.summary,roster:merged.roster.length,rosterChanges:merged.changes.length,departed:merged.roster.filter(e=>employmentStatus(e)==='離職').length};
 if(input.preview===true)return json({preview:true,revision:current.record.revision,summary});
 // Both the new roster and the credential directory become current with one conditional pointer write.
 const key=EMP_ROOT+'directories/'+crypto.randomUUID()+'.json';await bucket.put(key,JSON.stringify({users:prepared.users,importedAt:new Date().toISOString(),filename:textValue(input.filename||'員工名單.xlsx','檔名',240)}));
 const snapshot={...current.record.snapshot,roster:merged.roster};let next;
 try{next=await publishVersion(bucket,current,{action:'employee-directory',filename:textValue(input.filename||'員工名單.xlsx','檔名',240),hasOriginal:false,quarter:null,employeeDirectoryKey:key,snapshot})}catch(e){await bucket.delete(key);throw e}
 return json({updated:true,revision:next.revision,summary},201);
}

// ASSETS, INITIAL and the shared validation model are prepended by scripts/build.mjs.
const ROOT='small-step/v1/',CURRENT=ROOT+'current.json',SITE_ORIGIN='https://small-step-analytics-2026.workspace-926599.chatgpt.site';
const JSON_HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
function json(value,status=200,extra={}){return new Response(JSON.stringify(value),{status,headers:{...JSON_HEADERS,...extra}})}
function versionKey(id){return ROOT+'versions/'+id+'.json'}
function validRevision(id){if(typeof id!=='string'||!(id==='initial'||/^[a-f0-9-]{36}$/.test(id)))fail('版本識別碼不正確。',400);return id}
function initialVersion(){return {revision:'initial',parent:null,createdAt:null,action:'initial',filename:'最初匯入的兩季資料',quarter:null,hasOriginal:false,snapshot:INITIAL}}
function upgradeSnapshot(snapshot){const copy=structuredClone(snapshot);for(const q of copy.data)for(const p of q.people){if(p.months.every(m=>m.paperSignature!==undefined))continue;const seed=INITIAL.data.find(x=>x.id===q.id)?.people.find(x=>x.name===p.name);if(seed&&seed.paperSignature===p.paperSignature&&seed.digitalSignature===p.digitalSignature&&p.months.every(m=>{const sm=seed.months.find(x=>x.month===m.month);return ['paperBase','paperBonus','paper','digitalBase','digitalBonus','digital'].every(k=>sm?.[k]===m[k])})){p.months=p.months.map(m=>({...m,paperSignature:seed.months.find(x=>x.month===m.month).paperSignature,digitalSignature:seed.months.find(x=>x.month===m.month).digitalSignature}))}}if(!copy.notes)copy.notes=INITIAL.notes.filter(n=>{const q=copy.data.find(q=>q.id===n.quarter),seed=INITIAL.data.find(q=>q.id===n.quarter);return q&&q.people.length===seed.people.length&&q.people.every(p=>{const sp=seed.people.find(x=>x.name===p.name),m=p.months.find(x=>x.month===n.month),sm=sp?.months.find(x=>x.month===n.month);return sm&&m.digital===sm.digital&&m.digitalBonus===sm.digitalBonus})});if(!copy.roster)copy.roster=rosterFromData(copy.data,INITIAL.roster);return copy}
async function getVersion(bucket,id){validRevision(id);if(id==='initial')return initialVersion();const obj=await bucket.get(versionKey(id));if(!obj)fail('找不到這個版本。',404);const record=await obj.json();record.snapshot=upgradeSnapshot(record.snapshot);return record}
async function readCurrent(bucket){const pointer=await bucket.get(CURRENT);if(!pointer)return {pointer:null,record:initialVersion(),employeeDirectoryKey:null};const p=await pointer.json();return {pointer,record:await getVersion(bucket,p.revision),employeeDirectoryKey:p.employeeDirectoryKey||null}}
function datasetResponse(record){return {schemaVersion:1,revision:record.revision,updatedAt:record.createdAt,action:record.action,filename:record.filename,data:publicQuarterData(record.snapshot),stories:record.snapshot.stories,notes:record.snapshot.notes||[],reviewMeta:record.snapshot.reviewMeta,roster:(record.snapshot.roster||[]).map(({name,department,group,status,hireDate,leaveDate,knownActiveBy})=>({name,department,group,status:employmentStatus({status,hireDate,leaveDate,knownActiveBy})}))}}
function historyItem(r){return {revision:r.revision,parent:r.parent,createdAt:r.createdAt,action:r.action,filename:r.filename,quarter:r.quarter,months:r.months,hasOriginal:r.hasOriginal,rosterCount:r.snapshot.roster?.length,summary:r.snapshot.data.map(q=>quarterSummary(q,r.snapshot.stories))}}
async function history(bucket,current){let r=current,out=[];for(let i=0;r&&i<25;i++){out.push(historyItem(r));r=r.parent?await getVersion(bucket,r.parent):null}return out}
function writeGuard(request){const origin=request.headers.get('origin'),own=new URL(request.url).origin;if(origin&&origin!==own&&origin!==SITE_ORIGIN)fail('不接受其他網站送出的更新請求。',403);if(request.headers.get('sec-fetch-site')==='cross-site'||request.headers.get('x-small-step-write')!=='1')fail('請從資料更新後台操作。',403)}
async function publishVersion(bucket,current,details,rawFile=null){
 const revision=crypto.randomUUID(),record={revision,parent:current.record.revision,createdAt:new Date().toISOString(),...details};
 const key=versionKey(revision),originalKey=ROOT+'originals/'+revision+'.xlsx';
 await bucket.put(key,JSON.stringify(record),{httpMetadata:{contentType:'application/json'}});
 if(rawFile)await bucket.put(originalKey,rawFile,{httpMetadata:{contentType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}});
 let saved;try{saved=await bucket.put(CURRENT,JSON.stringify({revision,employeeDirectoryKey:details.employeeDirectoryKey||current.employeeDirectoryKey||null}),{onlyIf:current.pointer?{etagMatches:current.pointer.etag}:{etagDoesNotMatch:'*'},httpMetadata:{contentType:'application/json'}})}catch(e){await bucket.delete(rawFile?[key,originalKey]:[key]);throw e}
 if(!saved){await bucket.delete(rawFile?[key,originalKey]:[key]);fail('其他分頁已更新資料，請重新載入後再預覽。',409)}return record;
}
async function updateDataset(request,bucket){
 writeGuard(request);if(!request.headers.get('content-type')?.startsWith('multipart/form-data'))fail('請使用檔案上傳表單。',400);if(Number(request.headers.get('content-length')||0)>21*1024*1024)fail('上傳內容過大。',413);
 const form=await request.formData(),file=form.get('file'),raw=form.get('payload');if(!file||typeof file==='string'||file.size>MAX_XLSX_BYTES||!file.size||!file.name.toLowerCase().endsWith('.xlsx'))fail('請上傳 15 MB 以下的 .xlsx 檔案。');if(typeof raw!=='string'||raw.length>5*1024*1024)fail('資料格式不正確或內容過大。');
 let payload;try{payload=JSON.parse(raw)}catch{fail('無法解析上傳資料。',400)}if(payload.mode==='raw')return updateRawDataset(bucket,file,payload);const quarter=normalizedQuarter(payload.quarter);if(quarter.filename!==file.name)fail('預覽與上傳檔名不一致，請重新選擇檔案。');const stories=normalizedStories(payload.stories,quarter),current=await readCurrent(bucket);if(payload.expectedRevision!==current.record.revision)fail('網站資料已變更，請重新載入並重新預覽。',409);
 const previous=current.record.snapshot.data.find(q=>q.id===quarter.id),warnings=changeWarnings(previous,quarter,stories);if(warnings.length&&!payload.acknowledgedWarnings)fail('這次更新有注意事項，請先確認預覽中的提醒。');
 const noteUnchanged=!payload.electronicNotes||JSON.stringify(current.record.snapshot.notes.filter(n=>n.quarter===quarter.id))===JSON.stringify(normalizedElectronicNotes(payload.electronicNotes,quarter));const unchanged=noteUnchanged&&JSON.stringify(previous)===JSON.stringify(quarter)&&JSON.stringify(current.record.snapshot.stories.filter(s=>s.quarter===quarter.id))===JSON.stringify(stories);if(unchanged)return json({unchanged:true,message:'資料與目前版本相同，未新增更新紀錄。',revision:current.record.revision});
 const bytes=await file.arrayBuffer(),magic=new Uint8Array(bytes.slice(0,4));if(magic[0]!==80||magic[1]!==75||magic[2]!==3||magic[3]!==4)fail('檔案不是有效的 .xlsx 壓縮格式。');
 const snapshot={data:current.record.snapshot.data.filter(q=>q.id!==quarter.id).concat(quarter).sort((a,b)=>a.id.localeCompare(b.id)),stories:current.record.snapshot.stories.filter(s=>s.quarter!==quarter.id).concat(stories).sort((a,b)=>a.month-b.month||a.source.localeCompare(b.source)||a.row-b.row),roster:current.record.snapshot.roster,notes:current.record.snapshot.notes.filter(n=>n.quarter!==quarter.id).concat(normalizedElectronicNotes(payload.electronicNotes||[],quarter))};snapshot.roster=rosterFromData(snapshot.data,snapshot.roster);
 const next=await publishVersion(bucket,current,{action:'upload',filename:quarter.filename,quarter:quarter.id,hasOriginal:true,snapshot},bytes);return json({updated:true,revision:next.revision,updatedAt:next.createdAt,summary:quarterSummary(quarter,stories)},201);
}
async function rawPreview(request,bucket){writeGuard(request);const payload=await request.json(),current=await readCurrent(bucket);if(payload.expectedRevision!==current.record.revision)fail('網站資料已變更，請重新整理後再預覽。',409);const result=applyRawImport(current.record.snapshot,payload);return json({revision:current.record.revision,summary:result.summary,months:result.months,recordCount:result.recordCount,changes:result.changes,warnings:result.warnings,rosterSummary:result.rosterSummary,previous:current.record.snapshot.data.map(q=>quarterSummary(q,current.record.snapshot.stories))})}
async function updateRawDataset(bucket,file,payload){const current=await readCurrent(bucket);if(payload.expectedRevision!==current.record.revision)fail('網站資料已變更，請重新載入並重新預覽。',409);if(payload.filename!==file.name)fail('預覽與上傳檔名不一致。');const result=applyRawImport(current.record.snapshot,payload);if(result.warnings.length&&!payload.acknowledgedWarnings)fail('請先確認預覽中的注意事項。');if(JSON.stringify(result.snapshot)===JSON.stringify(current.record.snapshot))return json({unchanged:true,message:'資料與目前版本相同，未新增更新紀錄。',revision:current.record.revision});const bytes=await file.arrayBuffer(),magic=new Uint8Array(bytes.slice(0,4));if(magic[0]!==80||magic[1]!==75||magic[2]!==3||magic[3]!==4)fail('檔案不是有效的 .xlsx 壓縮格式。');const next=await publishVersion(bucket,current,{action:'upload',format:'raw',filename:file.name,quarter:null,months:result.months,employeeChangeCount:result.changes.length,hasOriginal:true,snapshot:result.snapshot},bytes);return json({updated:true,revision:next.revision,updatedAt:next.createdAt,summary:result.summary,rosterSummary:result.rosterSummary},201)}
async function restoreDataset(request,bucket){writeGuard(request);if(!request.headers.get('content-type')?.startsWith('application/json'))fail('還原請求格式不正確。',400);const input=await request.json(),current=await readCurrent(bucket);if(input.expectedRevision!==current.record.revision)fail('網站資料已變更，請重新整理後再還原。',409);const target=await getVersion(bucket,validRevision(input.revision));if(target.revision===current.record.revision)return json({unchanged:true,revision:target.revision});const next=await publishVersion(bucket,current,{action:'restore',filename:`還原：${target.filename}`,quarter:target.quarter,hasOriginal:false,restoredFrom:target.revision,snapshot:target.snapshot});return json({restored:true,revision:next.revision,updatedAt:next.createdAt});}
async function api(request,env,path){
 if(!env.BUCKET)fail('更新服務尚未完成設定，請聯繫網站維護人員。',503);const bucket=env.BUCKET;
 if(path==='/api/admin/review-export'||path==='/api/admin/review-import'){const key=request.headers.get('x-small-step-review-key');let actor='owner-maintenance';if(!(env.REVIEW_MAINTENANCE_KEY&&key&&authEqual(key,env.REVIEW_MAINTENANCE_KEY))){actor=(await requireAdminSession(request,bucket)).user.id}if(path.endsWith('export')&&request.method==='GET')return reviewExport(bucket);if(path.endsWith('import')&&request.method==='POST')return reviewImport(request,bucket,actor);fail('請使用審核管理表單。',405)}
 if(path==='/api/employee/my-notes'&&request.method==='GET')return employeeMyNotes(request,bucket);
 if(path==='/api/admin/directory-sync'){const key=request.headers.get('x-small-step-directory-key');if(!(env.DIRECTORY_IMPORT_KEY&&key&&authEqual(key,env.DIRECTORY_IMPORT_KEY))){const session=await requireAdminSession(request,bucket);if(session.user.role!=='admin')fail('僅管理員可同步員工名單與登入帳號。',403);}if(request.method!=='POST')fail('請使用名單更新表單。',405);return employeeDirectorySync(request,bucket)}
 if(path.startsWith('/api/employee/auth/')){await seedEmployeeAccount(bucket,env);return employeeAuthApi(request,bucket,path);}
 if(path==='/api/employee/notes'&&request.method==='POST')return submitEmployeeNote(request,bucket);
 if(path==='/api/admin/employee-accounts')return employeeAccountsApi(request,bucket);
 if(path.startsWith('/api/admin/auth/'))return authApi(request,bucket,path);if(path.startsWith('/api/admin/'))await requireAdminSession(request,bucket);
 if(path==='/api/dataset'&&request.method==='GET'){await requireEmployee(request,bucket);const current=await readCurrent(bucket),snapshot=await effectiveSnapshot(bucket,current.record.snapshot),payload=datasetResponse({...current.record,snapshot});payload.data=payload.data.map(({managers,...q})=>q);payload.notes=payload.notes.map(({employeeId,createdAt,reviewedBy,...n})=>n);return json(payload)}
 if(path==='/api/admin/reviews'){if(request.method==='GET')return adminReviewList(request,bucket);if(request.method==='POST')return adminReviewUpdate(request,bucket);fail('請使用審核管理表單。',405)}
 if(path==='/api/admin/template'&&request.method==='GET'){const response=assetResponse('/upload-template.xlsx',request);response.headers.set('cache-control','private, no-store');return response}
 if(path==='/api/admin/dataset'&&request.method==='GET')return json(datasetResponse((await readCurrent(bucket)).record));
 if(path==='/api/admin/manager-dataset'&&request.method==='GET'){const current=await readCurrent(bucket);return json(datasetResponse({...current.record,snapshot:await effectiveSnapshot(bucket,current.record.snapshot)}))}
 if(path==='/api/admin/web-notes'&&request.method==='GET')return json({notes:(await webNotes(bucket)).notes});
 if(path==='/api/admin/status'&&request.method==='GET'){const current=await readCurrent(bucket),effective=await effectiveSnapshot(bucket,current.record.snapshot);return json({webNoteCount:(await webNotes(bucket)).notes.length,revision:current.record.revision,updatedAt:current.record.createdAt,filename:current.record.filename,schemaVersion:1,summary:effective.data.map(q=>quarterSummary(q,effective.stories)),roster:current.record.snapshot.roster,history:await history(bucket,current.record)})}
 if(path==='/api/admin/preview'&&request.method==='POST')return rawPreview(request,bucket);
 if(path==='/api/admin/update'&&request.method==='POST')return updateDataset(request,bucket);
 if(path==='/api/admin/restore'&&request.method==='POST')return restoreDataset(request,bucket);
 if(path==='/api/admin/backup'&&request.method==='GET'){const id=new URL(request.url).searchParams.get('revision'),current=id?await getVersion(bucket,validRevision(id)):(await readCurrent(bucket)).record;return json({...datasetResponse(current),webSubmissions:(await webNotes(bucket)).notes,electronicReview:await reviewDocument(bucket).then(({obj,...d})=>d),roster:current.snapshot.roster,exportedAt:new Date().toISOString()},200,{'content-disposition':`attachment; filename="small-step-backup-${current.revision}.json"`})}
 if(path==='/api/admin/original'&&request.method==='GET'){const id=validRevision(new URL(request.url).searchParams.get('revision')),record=await getVersion(bucket,id);if(!record.hasOriginal)fail('這個版本沒有另存原始 Excel。',404);const original=await bucket.get(ROOT+'originals/'+id+'.xlsx');if(!original)fail('找不到原始 Excel。',404);return new Response(original.body,{headers:{'content-type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','content-disposition':`attachment; filename*=UTF-8''${encodeURIComponent(record.filename)}`,'cache-control':'no-store','x-content-type-options':'nosniff'}})}
 if((path==='/data.json'||path==='/stories.json')&&request.method==='GET'){const current=await readCurrent(bucket);return json(path==='/data.json'?current.record.snapshot.data:current.record.snapshot.stories)}
 return json({error:'找不到這個操作。'},404);
}
function assetResponse(path,request){const item=ASSETS[path];if(!item)return new Response('Not found',{status:404});const headers={'content-type':item.type,'content-encoding':'gzip','cache-control':'no-cache','x-content-type-options':'nosniff','etag':item.etag,...(path==='/sw.js'?{'service-worker-allowed':'/','cache-control':'no-cache, no-store, must-revalidate'}:{})};if(request.headers.get('if-none-match')===item.etag)return new Response(null,{status:304,headers});const bytes=Uint8Array.from(atob(item.bytes),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers,encodeBody:'manual'})}
export default {async fetch(request,env){try{let path=new URL(request.url).pathname;if(path==='/'||path==='/index.html')path='/index.html';if(path==='/admin')path='/admin.html';if(path==='/index.html'){if(!env.BUCKET)fail('登入服務尚未完成設定。',503);try{await requireEmployee(request,env.BUCKET)}catch(e){if(e.status!==401)throw e;return new Response(null,{status:302,headers:{location:'/login.html','cache-control':'no-store'}})}}const protectedFile=['/data.json','/stories.json','/roster.json','/electronic-notes.json'].includes(path)||/\.(xlsx|csv|zip|pdf)$/i.test(path);if(protectedFile){if(!env.BUCKET)fail('檔案服務尚未完成設定。',503);await requireAdminSession(request,env.BUCKET)}if(path.startsWith('/api/')||path==='/data.json'||path==='/stories.json')return await api(request,env,path);if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const response=assetResponse(path,request);if(path==='/index.html'||path==='/login.html')response.headers.set('cache-control','private, no-store');if(protectedFile)response.headers.set('cache-control','private, no-store');return response}catch(e){return json({error:e.status?e.message:'資料服務暫時無法使用，請稍後重新整理。'},e.status||500)}}};
